reproducibility.base_script:
import collections,hashlib,random,math,statistics,json,string
from vs import refcorpus
AB=string.ascii_lowercase
BOOKS=('it_dante','es_buenamor','en_paston');SEEDS=(4001,4002,4003);N=30000

def score(ws):
 count=collections.Counter(ws);n=len(ws);pref=collections.Counter()
 for w,v in count.items():
  if len(w)>=2:pref[w[:2]]+=v
 out={}
 for L in range(4,9):
  xy=[(math.log2(v/n),math.log2((n-v+1)/(pref[w[:2]]-v+1))) for w,v in count.items() if len(w)==L]
  assert len(xy)>=100
  x,y=zip(*xy);mx=statistics.mean(x);my=statistics.mean(y);out[str(L)]={'types':len(x),'mean':my,'slope':sum((a-mx)*(b-my) for a,b in xy)/sum((a-mx)**2 for a in x)}
 return out

def make(ws,k,weighted,seed):
 rng=random.Random(seed);types=sorted(set(ws));prefixes=[''.join([a,b]) for a in AB for b in AB];rng.shuffle(prefixes);prefixes=prefixes[:k];weight=[1/(i+1) for i in range(k)] if weighted else None
 used={w for w in types if len(w)<4};mapping={w:w for w in used}
 for w in types:
  if len(w)<4:continue
  while True:
   pre=rng.choices(prefixes,weights=weight,k=1)[0];new=pre+''.join(rng.choices(AB,k=len(w)-2))
   if new not in used:break
  used.add(new);mapping[w]=new
 out=[mapping[w] for w in ws]
 before=collections.Counter(ws);after=collections.Counter(out)
 assert len(before)==len(after) and sorted(before.values())==sorted(after.values())
 assert all(len(w)==len(mapping[w]) for w in mapping)
 return out

out={'books':BOOKS,'seeds':SEEDS,'N':N,'results':{}}
for book in BOOKS:
 e=next(x for x in refcorpus.pins() if x['id']==book);assert hashlib.sha256(open(e['file'],'rb').read()).hexdigest()==e['sha256'];ws=' '.join(refcorpus.blocks_of(book)).split()[:N];assert len(ws)==N
 row={'source':score(ws),'synthetic':{}}
 for k,weighted in [(16,False),(64,False),(16,True)]:
  key=f'{k}_'+('zipf' if weighted else 'uniform');row['synthetic'][key]=[score(make(ws,k,weighted,s)) for s in SEEDS]
 out['results'][book]=row
print(json.dumps(out,indent=2))

