import json,random,collections,hashlib
from vs import refcorpus
from string import ascii_lowercase as AB
src=open('/tmp/voy_pj028_synthetic.py').read().split("out={'books':")[0];exec(compile(src,'/tmp/voy_pj028_synthetic.py','exec'))
def make_rank(ws,k,seed):
 rng=random.Random(seed);freq=collections.Counter(ws);alltypes=sorted(freq);short={w for w in alltypes if len(w)<4};ordered=sorted((w for w in alltypes if len(w)>=4),key=lambda w:(-freq[w],w));prefixes=[a+b for a in AB for b in AB];rng.shuffle(prefixes);prefixes=prefixes[:k];used=set(short);mapping={w:w for w in short}
 for i,w in enumerate(ordered):
  pre=prefixes[min(k-1,i*k//len(ordered))]
  while True:
   new=pre+''.join(rng.choices(AB,k=len(w)-2))
   if new not in used:break
  used.add(new);mapping[w]=new
 out=[mapping[w] for w in ws];new=collections.Counter(out)
 assert sorted(freq.values())==sorted(new.values()) and all(len(w)==len(mapping[w]) for w in alltypes)
 return out
out={}
for book in BOOKS:
 e=next(x for x in refcorpus.pins() if x['id']==book);assert hashlib.sha256(open(e['file'],'rb').read()).hexdigest()==e['sha256'];ws=' '.join(refcorpus.blocks_of(book)).split()[:N];assert len(ws)==N
 out[book]={'source':score(ws),'rank_96':[score(make_rank(ws,96,seed)) for seed in SEEDS],'rank_128':[score(make_rank(ws,128,seed)) for seed in SEEDS]}
